/// <summary>
/// AVA
/// </summary>
/// <param name="sender">FormDataSource</param>
/// <param name="e">FormDataSourceEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormDataSourceEventHandler(formDataSourceStr(smmBusRelTable, smmBusRelTable), FormDataSourceEventType::Initialized)]
public static void smmBusRelTable_OnInitialized(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormDataSource  fds = sender;

    fds.object(fieldNum(smmBusRelTable, MandatoryCreditLimit)).visible(false);
    fds.object(fieldNum(smmBusRelTable, CreditRating)).visible(false);
    fds.object(fieldNum(smmBusRelTable, CreditMax)).visible(false);
}



